import React from 'react';

import { omitTransientProps } from 'utils/emotion';

import { StyledTabsRoot } from '../Tabs.styles';
import type { TabsRootProps } from '../Tabs.types';

export const TabsRoot = ({
  children,
  defaultValue,
  ...props
}: TabsRootProps): JSX.Element => (
  <StyledTabsRoot defaultValue={defaultValue} {...omitTransientProps(props)}>
    {children}
  </StyledTabsRoot>
);

TabsRoot.displayName = 'Tabs.Root';
